sketch:
// IR remote — NEC codes over a 38 kHz receiver.
//
// The receiver demodulates the carrier, leaving a low pulse for each burst.
// The library records the edges and decodes address/complement/command bytes.
// Click a button on the remote on the canvas.

#include <IRremote.h>

const int RECV_PIN = 2;
IRrecv irrecv(RECV_PIN);
decode_results results;

void setup() {
  Serial.begin(9600);
  irrecv.enableIRIn();
}

void loop() {
  if (irrecv.decode(&results)) {
    Serial.print("ir=0x");
    Serial.print(results.value, HEX);
    Serial.print(" command=0x");
    Serial.println(results.command, HEX);
    irrecv.resume();
  }
  delay(50);
}
